  "description": "Converts a planet's mass from Jupiter mass units to Earth mass units.",
  "definition": "Given a planet's mass in Jupiter masses ($M_J$), its mass in Earth masses ($M_E$) is: $M_E = M_J \\times 317.83$"
}

{
  "id": 2,
  "knowledge": "Planet Radius in Earth Units",
  "description": "Converts a planet's radius from Jupiter radius units to Earth radius units.",
  "definition": "Given a planet's radius in Jupiter radii ($R_J$), its radius in Earth radii ($R_E$) is: $R_E = R_J \\times 11.209$"
}

