FROM physical_properties 
WHERE objectlink = 2583;

SELECT objectlink, massjup, radjup, densvalue
FROM physical_properties 
WHERE objectlink = 2583;

SELECT ROUND(SQRT(317.83 / 11.209) * 11.186 * SQRT(massjup / radjup)) AS escape_velocity_kms
FROM physical_properties 
WHERE objectlink = 2583;
